import os
import subprocess
import logging
import threading
import socket
import json
import sys

# Constants
TARGET_DIR = "./target"
LOG_FILE = os.path.join(TARGET_DIR, "service.log")
SERVICE_NAME = ".hidden_service"
HOST = "localhost"
PORT = 65432
COMMANDS = ["ls", "pwd", "whoami"]  # Allowed system management commands


def setup_logging():
    os.makedirs(TARGET_DIR, exist_ok=True)
    logging.basicConfig(
        filename=LOG_FILE,
        level=logging.INFO,
        format="%(asctime)s [%(levelname)s]: %(message)s",
    )


def create_hidden_service():
    service_path = os.path.join(TARGET_DIR, SERVICE_NAME)
    try:
        with open(service_path, "w") as f:
            f.write("# Hidden service placeholder\n")
        os.chmod(service_path, 0o700)
        logging.info(f"Hidden service created: {service_path}")
    except Exception as e:
        logging.error(f"Failed to create hidden service: {e}")


def execute_command(command):
    try:
        if command not in COMMANDS:
            raise ValueError(f"Command '{command}' is not allowed.")
        result = subprocess.run(
            command, shell=True, capture_output=True, text=True
        )
        if result.returncode == 0:
            logging.info(f"Command executed: {command}, Output: {result.stdout.strip()}")
            return {"success": True, "output": result.stdout.strip()}
        else:
            logging.error(f"Command failed: {command}, Error: {result.stderr.strip()}")
            return {"success": False, "error": result.stderr.strip()}
    except Exception as e:
        logging.error(f"Error executing command '{command}': {e}")
        return {"success": False, "error": str(e)}


def handle_client_connection(client_socket):
    try:
        data = client_socket.recv(1024).decode("utf-8")
        request = json.loads(data)
        command = request.get("command")
        if not command:
            response = {"success": False, "error": "No command provided"}
        else:
            response = execute_command(command)
        client_socket.sendall(json.dumps(response).encode("utf-8"))
    except Exception as e:
        logging.error(f"Error handling client connection: {e}")
    finally:
        client_socket.close()


def start_remote_interface():
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        server_socket.bind((HOST, PORT))
        server_socket.listen(5)
        logging.info(f"Remote interface listening on {HOST}:{PORT}")

        for _ in range(3):  # Handle up to 3 client connections for this demo
            try:
                client_socket, _ = server_socket.accept()
                threading.Thread(
                    target=handle_client_connection, args=(client_socket,)
                ).start()
            except Exception as e:
                logging.error(f"Error accepting connection: {e}")
    except Exception as e:
        logging.error(f"Failed to start remote interface: {e}")
    finally:
        server_socket.close()


def main():
    setup_logging()
    create_hidden_service()
    start_remote_interface()


if __name__ == "__main__":
    main()

import os
